pub fn propertyHelper(self: *BorderRadiusHandler, d: *css.DeclarationList, ctx: *css.PropertyHandlerContext, comptime prop: []const u8, val: *const Size2D(LengthPercentage), vp: css.VendorPrefix) void {
            if ((self.category != .physical)) {
                _ = self.flush(d, ctx);
            }
            _ = self.maybeFlush(d, ctx, prop, val, vp);
            if (@field(self, prop)) |*existing| {
                _ = &existing;
                (existing.*) = .{ val.deepClone(ctx.allocator), vp };
            } else {
                @field(self, prop) = .{ val.deepClone(ctx.allocator), vp };
                self.has_any = true;
            }
            self.category = .physical;
    }

pub fn logicalPropertyHelper(self: *BorderRadiusHandler, d: *css.DeclarationList, ctx: *css.PropertyHandlerContext, comptime prop: []const u8, val: *const css.Property) void {
            if ((self.category != .logical)) {
                _ = self.flush(d, ctx);
            }
            @field(self, prop) = val.deepClone(ctx.allocator);
            self.category = .logical;
            self.has_any = true;
    }
};

const Printer = css.Printer;
const PrintErr = css.PrintErr;
const LengthPercentage = css.css_values.length.LengthPercentage;
const Size2D = css.css_values.size.Size2D;
const Rect = css.css_values.rect.Rect;
const Property = css.Property;
const VendorPrefix = css.VendorPrefix;
const PropertyIdTag = css.PropertyIdTag;
const RadiusAndPrefix = struct { Size2D(LengthPercentage), css.VendorPrefix };
const Allocator = std.mem.Allocator;

pub fn isBorderRadiusProperty(property_id: PropertyIdTag) bool {
        if (isLogicalBorderRadiusProperty(property_id)) {
            return true;
        }
        return (switch (property_id) {
.@"border-top-left-radius", .@"border-top-right-radius", .@"border-bottom-right-radius", .@"border-bottom-left-radius", .@"border-radius" => true,
else => false,
});
}

pub fn isLogicalBorderRadiusProperty(property_id: PropertyIdTag) bool {
        return (switch (property_id) {
.@"border-start-start-radius", .@"border-start-end-radius", .@"border-end-end-radius", .@"border-end-start-radius" => true,
else => false,
});
}
